
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_xc_otpss_d_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_xc_otpss_d", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.613239620138371e+00, -4.523108050639105e+00, -4.396815326420756e+00, -4.221875174410744e+00, -3.983509809476358e+00, -3.666287690348301e+00, -3.258039589057942e+00, -2.757013007163820e+00, -2.182744479079473e+00, -1.589582740514186e+00, -1.045741602958372e+00, -7.248892672238130e-01, -6.478141635764164e-01, -5.446415993375462e-01, -3.859745293353425e-01, -2.368105322958545e-01, -1.344969382415882e-01, -4.921506493834509e-02, -1.066077272369809e-02, -1.198680562875318e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


